{
  "category_edits": [
    {
      "category": "sequence_interest",
      "rationale": "Index positions by observed sequence order so short histories share position representations regardless of left padding. Padding retains position zero. The generated predictor imports HSTURec from train.py, so training and inference use the identical rule without checkpoint shape changes. History truncation, final-position readout, gated attention, scoring, loss and optimizer remain unchanged.",
      "edits": [
        {
          "find": "        pos = torch.arange(maxlen, device=seq.device).unsqueeze(0).expand(batch_size, -1) + 1\n        pos = pos * (seq != 0).long()",
          "replace": "        observed = (seq != 0).long()\n        pos = observed.cumsum(dim=1) * observed"
        }
      ]
    }
  ],
  "change_summary": "Use cumulative nonpadding position IDs in the shared HSTU model for all four dataset routes, preserving embedding shapes and predictor consistency."
}
